    msg.payload = { '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'], '@type': 'TransferError', providerPid: 'urn:facis:dsp:unknown', consumerPid: (body && body.consumerPid) || 'urn:facis:dsp:unknown', code: 'agreement_not_held_by_caller', reason: ['agreement ' + body.agreementId + ' is held by a different counterparty'] };
