// dsp-tx-kafka-admin — NF-3 (FR-DP-002): real Kafka topic create/delete via
// node-rdkafka's AdminClient, authenticating with the connector's OWN mTLS
// identity — the same certs every producer/consumer flow on this pod already
// uses (infrastructure/orce/kafka-certs-patch.yaml). No new credential is
// minted and none is ever delivered to callers (mTLS-only cluster; SASL is
// deliberately stripped from the build toolchain — init-deps-patch.yaml).
//
// Input msgs carry msg._kafkaAction:
//   'create' — from dsp-tx-create output 6, with msg._transferId,
//              msg._kafkaAccess, and the live req/res for the deferred
//              HTTP response.
//   'delete' — from dsp-tx-terminate output 3, fire-and-forget, with
//              msg._kafkaTopic only (no req/res).
// Outputs: [response, persist-trigger, metric-completed, metric-error]
//
// NOT harness-testable: needs node-rdkafka (native build) + a live broker.
// Covered by tests/e2e/dsp-kafka-transfer-e2e.js instead.
const action = msg._kafkaAction;
const conf = {
    'client.id': 'facis-dsp-connector-admin',
    'metadata.broker.list': env.get('DSP_KAFKA_BOOTSTRAP') || '212.132.83.222:9093',
    'security.protocol': 'ssl',
    'ssl.ca.location': '/etc/kafka-certs/ca.crt',
    'ssl.certificate.location': '/etc/kafka-certs/tls.crt',
    'ssl.key.location': '/etc/kafka-certs/tls.key',
    // Brokers are reached via bare IPs/NodePorts whose certs carry no
    // matching SANs — same setting as the kcat runbook and every other
    // FACIS Kafka client. Chain validation (mTLS) still applies.
    'ssl.endpoint.identification.algorithm': 'none'
};
const ERR = Kafka.CODES.ERRORS;

function adminOp(fn) {
    // AdminClient.create() connects synchronously and throws on failure
    // (verified against node-rdkafka v3.6.1 lib/admin.js).
    return new Promise((resolve, reject) => {
        let client;
        try { client = Kafka.AdminClient.create(conf); }
        catch (e) { reject(e); return; }
        fn(client, (err) => {
            try { client.disconnect(); } catch (e) { /* best-effort cleanup */ }
            if (err) reject(err); else resolve();
        });
    });
}

function nowIso() { return new Date().toISOString().slice(0, -1) + '000+00:00'; }

if (action === 'delete') {
    const topic = msg._kafkaTopic;
    (async () => {
        try {
            await adminOp((c, cb) => c.deleteTopic(topic, 10000, cb));
            node.log('dsp-tx-kafka-admin: deleted topic ' + topic);
        } catch (err) {
            if (err && err.code === ERR.ERR_UNKNOWN_TOPIC_OR_PART) {
                node.log('dsp-tx-kafka-admin: topic ' + topic + ' already gone');
            } else {
                // Non-fatal: the transfer is already TERMINATED and persisted
                // by dsp-tx-terminate. An orphaned topic is an ops cleanup
                // (kcat runbook), not a broken FSM.
                node.error('dsp-tx-kafka-admin: delete ' + topic + ' failed: ' + (err && err.message ? err.message : err));
            }
        }
    })();
    return null;
}

// action === 'create'
(async () => {
    const access = msg._kafkaAccess;
    const transferId = msg._transferId;
    const transfers = global.get('transfers') || {};
    const transfer = transfers[transferId];
    if (!transfer) {
        dspTransferError(500, 'internal_error', ['transfer ' + transferId + ' vanished before provisioning'], transferId, transferId);
        msg.headers = { 'Content-Type': 'application/json' };
        node.error('dsp-tx-kafka-admin: ' + msg.payload.reason[0]);
        node.send([msg, null, null, null]);
        return;
    }
    let metricOk = null;
    let metricErr = null;
    try {
        await adminOp((c, cb) => c.createTopic({
            topic: access.topic,
            // ponytail: 1 partition / RF 1 — a per-transfer dataset stream
            // wants strict ordering and is demonstrator-scale. The shared
            // firehose topics use 3/1 (infrastructure-prerequisites.md §3.2);
            // bump num_partitions here if a single transfer ever needs
            // parallel consumption.
            num_partitions: 1,
            replication_factor: 1
        }, 10000, cb));
        transfer.access = access;
        transfer.updatedAt = nowIso();
        metricOk = { payload: { family: 'facis_dsp_transfer_completions_total' } };
        node.log('Transfer ' + transferId + ' provisioned: topic ' + access.topic + ' created');
    } catch (err) {
        if (err && err.code === ERR.ERR_TOPIC_ALREADY_EXISTS) {
            // Idempotent: transfer ids are random, but a retry/replay of the
            // same create can race. The topic being there IS success.
            transfer.access = access;
            transfer.updatedAt = nowIso();
            metricOk = { payload: { family: 'facis_dsp_transfer_completions_total' } };
            node.log('Transfer ' + transferId + ': topic ' + access.topic + ' already existed');
        } else {
            // Attach the (already-computed) access object even on ERROR so
            // access.topic is recorded: if the broker committed the topic before
            // the client-side call errored (e.g. the 10s op timeout firing after a
            // successful create), terminate can still find the name to delete it.
            // Worst case the topic was never created and the later delete is a
            // harmless no-op (ERR_UNKNOWN_TOPIC_OR_PART).
            transfer.access = access;
            transfer.state = 'ERROR';
            transfer.reason = 'kafka topic provisioning failed: ' + (err && err.message ? err.message : err);
            transfer.updatedAt = nowIso();
            metricErr = { payload: { family: 'facis_dsp_transfer_errors_total' } };
            node.error('Transfer ' + transferId + ' ERROR: ' + transfer.reason);
        }
    }
    transfers[transferId] = transfer;
    global.set('transfers', transfers);
    // 202 {transferId} regardless of outcome — parity with the old
    // auto-complete path, which also 202'd and surfaced ERROR via GET.
    // Worst-case client wait is the 10s AdminClient op timeout.
    if (msg._dspBinding) {
        // Gap 1 (NF-7): DSP binding ACK for the kafka-streaming path. STARTED
        // (or ERROR) is reported as a TransferProcess; status stays 202 (NF-11).
        msg.statusCode = 202;
        msg.headers = { 'Content-Type': 'application/json' };
        msg.payload = { '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'], '@type': 'TransferProcess', providerPid: transfer.providerPid, consumerPid: transfer.consumerPid, state: transfer.state };
    } else {
        msg.payload = { transferId: transferId };
        msg.headers = { 'Content-Type': 'application/json' };
        msg.statusCode = 202;
    }
    node.send([msg, { payload: '' }, metricOk, metricErr]);
})();
return null;

// Gap 1 (NF-7): DSP binding surface for POST /dsp/transfers/request. Parses a
// dspace:TransferRequestMessage and maps it onto the existing create chain
// (iam.verify -> agreement bind -> create), which then answers with a DSP
// TransferProcess ACK because msg._dspBinding is set. No second state machine:
// this is a translation shim over the existing FSM (see this tab's info panel).
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
function pick() { for (let i = 0; i < arguments.length; i++) { const k = arguments[i]; if (body[k] !== undefined && body[k] !== null) return body[k]; } return undefined; }
function mapFormat(f) {
    // dct:format tokens vary by connector; anything naming kafka is the
    // streaming transfer, everything else is the default http-pull.
    if (!f) return 'http-pull';
    return String(f).toLowerCase().indexOf('kafka') !== -1 ? 'kafka-streaming' : 'http-pull';
}
const agreementId = pick('agreementId', 'dspace:agreementId');
const consumerPid = pick('consumerPid', 'dspace:consumerPid');
const callbackAddress = pick('callbackAddress', 'dspace:callbackAddress');
const format = mapFormat(pick('format', 'dct:format', 'dspace:format'));
// A TransferRequestMessage carries no assetId — the asset is fixed by the
// agreement. Resolve it from the finalized negotiation's offerId
// (offer:facis:<slug>:read -> dataset:facis:<slug>); an explicit assetId in the
// message wins if present, and an unresolved assetId is left undefined so the
// existing create node returns its normal 422 invalid_request TransferError.
let assetId = pick('assetId', 'dspace:assetId');
if (!assetId && agreementId) {
    const negs = global.get('negotiations') || {};
    const neg = Object.values(negs).find(function (n) { return n.agreementId === agreementId; });
    if (neg && neg.offerId) {
        assetId = neg.offerId.replace(/^offer:/, 'dataset:').replace(/:read$/, '');
    }
}
msg._dspBinding = true;
msg.payload = { agreementId: agreementId, assetId: assetId, consumerPid: consumerPid, format: format, parameters: { callbackAddress: callbackAddress || null } };
return msg;

function dspTransferError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'TransferError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

// Gap 1 (NF-7): DSP binding transitions POST /dsp/transfers/:providerPid/start
// (-> STARTED, resume) and /completion (-> COMPLETED). Same store, same matrix,
// same persist link as the FSM's suspend/terminate nodes — a binding surface,
// not a second state machine. Termination and suspension reuse dsp-tx-terminate
// / dsp-tx-suspend directly (terminate keeps its kafka topic-delete side effect).
// ponytail: /completion on a kafka-streaming transfer parks it at the terminal
// COMPLETED without deleting its topic (COMPLETED has no delete side effect);
// use /termination to reclaim a kafka topic. Demonstrator-acceptable — the TCK
// completion tests drive http-pull-style transfers.
const VALID = {
    REQUESTED: new Set(['STARTED','TERMINATED','ERROR']),
    STARTED:   new Set(['COMPLETED','SUSPENDED','TERMINATED','ERROR']),
    SUSPENDED: new Set(['STARTED','TERMINATED']),
    COMPLETED: new Set(),
    TERMINATED: new Set(),
    ERROR:     new Set(['TERMINATED'])
};
// Verb is the last path segment: .../start or .../completion.
const seg = String((msg.req && msg.req.url) || '').split('?')[0].split('/').filter(Boolean).pop();
const target = seg === 'start' ? 'STARTED' : 'COMPLETED';
const id = (msg.req.params && (msg.req.params.providerPid || msg.req.params.id));
const transfers = global.get('transfers') || {};
const cur = transfers[id];
if (!cur) {
    return [dspTransferError(404, 'not_found', ['Transfer ' + id + ' not found'], id, id), null];
}
const allowed = VALID[cur.state] || new Set();
if (!allowed.has(target)) {
    return [dspTransferError(400, 'invalid_state_transition',
        ['Invalid transition: ' + cur.state + ' \u2192 ' + target +
         '. Valid targets: ' + (Array.from(allowed).join(',') || '(terminal)')],
        cur.providerPid || id, cur.consumerPid || id), null];
}
const now = new Date().toISOString().slice(0, -1) + '000+00:00';
const reason = target === 'STARTED' ? 'Started by consumer' : 'Completed by consumer';
const updated = Object.assign({}, cur, { state: target, reason: reason, updatedAt: now });
transfers[id] = updated;
global.set('transfers', transfers);
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'], '@type': 'TransferProcess', providerPid: updated.providerPid, consumerPid: updated.consumerPid, state: updated.state };
return [msg, { payload: '' }];

// C-1: authenticate + holder-bind transfer state mutations/callbacks before any
// state transition. Runs after iam.verify (dsp-tx-mut-iam-call) and the iamRejected
// switch (in enforce mode a missing/invalid VP is already answered 401 upstream).
// Rejects a caller who is not the agreement counterparty with a typed 403, then
// routes the verified msg to the original transition handler.
function txError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'TransferError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}
// output order: 0 suspend, 1 terminate, 2 dsp-suspension, 3 dsp-termination, 4 dsp-transition(start/completion), 5 reject
const OUT = { suspend: 0, terminate: 1, suspension: 2, termination: 3, dsp: 4, reject: 5 };
const outputs = [null, null, null, null, null, null];
const url = String((msg.req && (msg.req.originalUrl || msg.req.url)) || '').split('?')[0];
let verb = null;
if (/\/suspension$/.test(url)) verb = 'suspension';
else if (/\/termination$/.test(url)) verb = 'termination';
else if (/\/suspend$/.test(url)) verb = 'suspend';
else if (/\/terminate$/.test(url)) verb = 'terminate';
else if (/\/(start|completion)$/.test(url)) verb = 'dsp';
if (!verb) {
    outputs[OUT.reject] = txError(404, 'not_found', ['Unknown transfer mutation route: ' + url]);
    return outputs;
}
// Holder binding: caller's verified DID must be the agreement counterparty.
// Dev bypass (_iamMode 'off') and warn-mode-without-resolved-identity do not block
// — parity with dsp-tx-agreement-check (the create path). Enforce mode never reaches
// here with a null identity because iamRejected was already routed to 401.
const params = (msg.req && msg.req.params) || {};
const id = params.id || params.providerPid;
if (msg._iamMode !== 'off' && msg.identity && msg.identity.did) {
    const transfers = global.get('transfers') || {};
    const cur = transfers[id];
    if (cur) {
        const negs = global.get('negotiations') || {};
        const neg = Object.values(negs).find(x => x.agreementId === cur.agreementId);
        if (neg && neg.counterparty && neg.counterparty !== msg.identity.did) {
            outputs[OUT.reject] = txError(403, 'unauthorized',
                ['Caller ' + msg.identity.did + ' is not the agreement counterparty for transfer ' + id],
                cur.providerPid || id, cur.consumerPid || id);
            return outputs;
        }
    }
}
outputs[OUT[verb]] = msg;
return outputs;
